head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.notiId;
scwin.strBzProcsNo, scwin.strProcsCd, scwin.strDtlSeq = "";
scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        scwin.strBzProcsNo = $c.stf.getQuery(frame.srcUrl, "BZ_PROCS_NO");
        scwin.strProcsCd = $c.stf.getQuery(frame.srcUrl, "LIST_ELIGTY_PROCS_CD");
        const tempDtlSeq = $c.stf.getQuery(frame.srcUrl, "LIST_ELIGTY_INVSTG_DTL_SEQ");
        if (tempDtlSeq !== "") {
            const splitStr = tempDtlSeq.split(",");
            if (splitStr.length > 1) {
                for (let i = 0, j = splitStr.length; i < j; i++) {
                    if (i !== 0) scwin.strDtlSeq += ",";
                    scwin.strDtlSeq += "'" + splitStr[i] + "'";
                }
            } else {
                scwin.strDtlSeq = tempDtlSeq;
            }
        }
        $c.elw.fn_searchCode();
        await scwin.read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20506_FILE.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Read_OnLoadError
 * @description trs_Read 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Read_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20506_FILE.trs_Read_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_userlist_OnDblClick
 * @description grd_userlist 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_userlist_OnDblClick = function(row, colid) {
    try {
        const bzProcsNo = dts_fileList.getCellData(row, "BZ_PROCS_NO");
        const procsNo = dts_fileList.getCellData(row, "LIST_ELIGTY_PROCS_CD");
        const dtlSeq = dts_fileList.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ");
        const fileSeq = dts_fileList.getCellData(row, "ATTACH_FILE_SEQ");
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            $c.elw.fn_filedown(bzProcsNo, procsNo, dtlSeq, fileSeq);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506_FILE.grd_userlist_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20506_FILE.btn_close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/RealInvstg.do",
        ref : "dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbdReason = "' ':"; // 초기값

    for (k = 1; k <= dts_Cod.getRowCount(); k++) {
        strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
    }
    $c.cm.setColumnProp(grd_userlist, 'LIST_ELIGTY_FILE_TP_CD', 'Data', strCbdReason);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} procsNo procsNo
 * @param {*} dtlSeq dtlSeq
 * @param {*} fileSeq fileSeq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(bzProcsNo, procsNo, dtlSeq, fileSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF20506_FILE.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsNo + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq + "&ATTACH_FILE_SEQ=" + fileSeq + "&gubun=42";
};

/**
 * @method
 * @name setDataHeader
 * @description set Data Header 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataHeader = function() {

    // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

};
